def pick_questions(level, count=QUESTIONS_PER_ROUND):
    """Return `count` questions for a level without crashing on small pools."""
    pool = QUESTIONS.get(level) or []
    if not pool:
        raise ValueError(f"No questions configured for level {level!r}")
    # Prefer unique questions; only repeat if the pool is smaller than count.
    if len(pool) < count:
        return random.choices(pool, k=count)
    return random.sample(pool, count)


def assert_quiz_integrity():
    """Fail fast if any answer is missing from its options."""
    errors = []
    for level, items in QUESTIONS.items():
        for item in items:
            if item["answer"] not in item["options"]:
                errors.append(f"{level}: {item['question'][:48]}...")
    if errors:
        raise ValueError("Quiz answer not in options:\n" + "\n".join(errors))

